"use client"

import * as React from "react"
import { cn } from "cn"

import { Divider } from "@/components/tecton/divider"
import { Meter } from "@/components/tecton/meter"

import type { DesignPoint, Metric, MetricCategory } from "../data"

type ComparisonListProps = React.ComponentProps<"div"> & {
  metrics: Metric[]
  designs: DesignPoint[]
  /** Ids of designs to show (defaults to all). */
  selected?: string[]
}

/**
 * Stacked comparison of the selected designs per metric: a bold total row
 * followed by category breakdowns, each rendered as a coloured bar.
 */
function ComparisonList({
  className,
  metrics,
  designs,
  selected,
  ...props
}: ComparisonListProps) {
  const visible = selected
    ? designs.filter((design) => selected.includes(design.id))
    : designs

  return (
    <div
      data-slot="comparison-list"
      className={cn("flex flex-col gap-6", className)}
      {...props}
    >
      {metrics.map((metric) => (
        <section key={metric.id} className="flex flex-col gap-3">
          <ComparisonGroup
            title={metric.label}
            emphasis
            metric={metric}
            category={metric.total}
            designs={visible}
          />
          {metric.categories.map((category) => (
            <React.Fragment key={category.id}>
              <Divider emphasis="subtle" />
              <ComparisonGroup
                title={category.label}
                metric={metric}
                category={category}
                designs={visible}
              />
            </React.Fragment>
          ))}
        </section>
      ))}
    </div>
  )
}

function ComparisonGroup({
  title,
  emphasis = false,
  metric,
  category,
  designs,
}: {
  title: string
  emphasis?: boolean
  metric: Metric
  category: MetricCategory
  designs: DesignPoint[]
}) {
  return (
    <div data-slot="comparison-group" className="flex flex-col gap-1.5">
      <h4 className={cn("text-xs font-medium", emphasis && "text-sm")}>{title}</h4>
      <div className="flex flex-col gap-1">
        {designs.map((design) => {
          const entry = category.values[design.id]
          if (!entry) return null
          return (
            <ComparisonBar
              key={design.id}
              design={design}
              value={entry.value}
              range={entry.range}
              max={metric.max}
              format={metric.format}
            />
          )
        })}
      </div>
    </div>
  )
}

function ComparisonBar({
  design,
  value,
  range,
  max,
  format,
}: {
  design: DesignPoint
  value: number
  range?: [number, number]
  max: number
  format: (value: number) => string
}) {
  return (
    <div
      data-slot="comparison-bar"
      className="grid grid-cols-[1fr_auto] items-center gap-3"
      style={{ "--series": design.color } as React.CSSProperties}
    >
      <Meter
        aria-label={`${design.name}: ${format(value)}`}
        value={value}
        minValue={0}
        maxValue={max}
        segments={1}
        size="sm"
        className="[&_[data-slot=meter-segment]>span]:bg-(--series)"
      />
      <span className="min-w-20 text-right font-mono text-xs tabular-nums">
        {format(value)}
        {range && (
          <span className="text-muted-foreground">
            {" "}
            –{format(range[1])}
          </span>
        )}
      </span>
    </div>
  )
}

export { ComparisonList, ComparisonGroup, ComparisonBar }
export type { ComparisonListProps }

"use client"

import * as React from "react"
import { cn } from "cn"
import {
  CartesianGrid,
  Cell,
  ReferenceLine,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts"

import {
  ChartContainer,
  ChartTooltip,
  type ChartConfig,
} from "@/components/ui/chart"

import { riskLabel, type DesignPoint } from "../data"

type QuadrantChartProps = React.ComponentProps<"div"> & {
  designs: DesignPoint[]
  /** Ids of the highlighted designs; others are dimmed. */
  selected?: string[]
  xLabel?: string
  yLabel?: string
}

/**
 * Cost (x) vs risk (y) bubble chart split into four quadrants by
 * reference lines at the mid-point of each axis. Bubble area = plan days.
 */
function QuadrantChart({
  className,
  designs,
  selected,
  xLabel = "Cost",
  yLabel = "Risk",
  ...props
}: QuadrantChartProps) {
  const config = React.useMemo<ChartConfig>(
    () =>
      Object.fromEntries(
        designs.map((design) => [
          design.id,
          { label: design.name, color: design.color },
        ])
      ),
    [designs]
  )

  const costs = designs.map((design) => design.cost)
  const xMin = Math.floor((Math.min(...costs) - 15) / 10) * 10
  const xMax = Math.ceil((Math.max(...costs) + 15) / 10) * 10
  const xMid = (xMin + xMax) / 2

  return (
    <ChartContainer
      data-slot="quadrant-chart"
      config={config}
      className={cn("aspect-square w-full rounded-md bg-surface-alt/60", className)}
      {...props}
    >
      <ScatterChart margin={{ top: 24, right: 24, bottom: 24, left: 8 }}>
        <CartesianGrid strokeDasharray="2 4" />
        <XAxis
          type="number"
          dataKey="cost"
          name={xLabel}
          domain={[xMin, xMax]}
          tickLine={false}
          axisLine={false}
          tickFormatter={(value: number) => `$${value}M`}
          fontSize={10}
        />
        <YAxis
          type="number"
          dataKey="risk"
          name={yLabel}
          domain={[0, 100]}
          tickLine={false}
          axisLine={false}
          tickFormatter={(value: number) => `${value}%`}
          width={36}
          fontSize={10}
        />
        <ZAxis type="number" dataKey="planDays" range={[240, 900]} />
        <ReferenceLine
          x={xMid}
          stroke="var(--border-strong)"
          label={{
            value: `High ${yLabel.toLowerCase()}`,
            position: "insideTopLeft",
            fill: "var(--muted-foreground)",
            fontSize: 10,
            dx: 6,
          }}
        />
        <ReferenceLine
          x={xMid}
          stroke="transparent"
          label={{
            value: `Low ${yLabel.toLowerCase()}`,
            position: "insideBottomLeft",
            fill: "var(--muted-foreground)",
            fontSize: 10,
            dx: 6,
          }}
        />
        <ReferenceLine
          y={50}
          stroke="var(--border-strong)"
          label={{
            value: `Low ${xLabel.toLowerCase()}`,
            position: "insideBottomLeft",
            fill: "var(--muted-foreground)",
            fontSize: 10,
          }}
        />
        <ReferenceLine
          y={50}
          stroke="transparent"
          label={{
            value: `High ${xLabel.toLowerCase()}`,
            position: "insideBottomRight",
            fill: "var(--muted-foreground)",
            fontSize: 10,
          }}
        />
        <ChartTooltip
          cursor={false}
          content={({ active, payload }) => {
            const point = payload?.[0]?.payload as DesignPoint | undefined
            if (!active || !point) return null
            return <QuadrantTooltip point={point} />
          }}
        />
        <Scatter data={designs} isAnimationActive={false}>
          {designs.map((design) => {
            const dimmed = selected && !selected.includes(design.id)
            return (
              <Cell
                key={design.id}
                fill={design.color}
                fillOpacity={dimmed ? 0.15 : 0.55}
                stroke={design.color}
                strokeOpacity={dimmed ? 0.4 : 1}
                strokeWidth={design.isRecommended ? 2 : 1}
              />
            )
          })}
        </Scatter>
      </ScatterChart>
    </ChartContainer>
  )
}

function QuadrantTooltip({ point }: { point: DesignPoint }) {
  return (
    <div className="grid min-w-36 gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl">
      <div className="flex items-center gap-1.5 font-medium">
        <span
          className="size-2.5 shrink-0 rounded-[2px]"
          style={{ background: point.color }}
        />
        {point.name}
        {point.isRecommended && (
          <span className="ml-auto text-[0.625rem] text-muted-foreground">
            Recommended
          </span>
        )}
      </div>
      <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-0.5 text-muted-foreground">
        <dt>Cost</dt>
        <dd className="text-right font-mono text-foreground tabular-nums">
          ${point.costRange[0]}–{point.costRange[1]}M
        </dd>
        <dt>Risk</dt>
        <dd className="text-right font-mono text-foreground tabular-nums">
          {point.risk}% · {riskLabel(point.risk)}
        </dd>
        <dt>Plan days</dt>
        <dd className="text-right font-mono text-foreground tabular-nums">
          {point.planDays}d
        </dd>
      </dl>
    </div>
  )
}

export { QuadrantChart, QuadrantTooltip }
export type { QuadrantChartProps }

"use client"

import * as React from "react"
import { cn } from "cn"
import { CrownIcon, PanelRightIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Chip } from "@/components/tecton/chip"
import {
  Panel,
  PanelActions,
  PanelContent,
  PanelHeader,
  PanelTitle,
} from "@/components/tecton/panel"
import {
  SelectField,
  SelectFieldItem,
} from "@/components/tecton/select-field"

import { ComparisonList } from "./components/comparison-list"
import { QuadrantChart } from "./components/quadrant-chart"
import { axisOptions, designs as allDesigns, metrics, type DesignPoint } from "./data"

type CostVsRiskPanelProps = Omit<React.ComponentProps<typeof Panel>, "children"> & {
  designs?: DesignPoint[]
  defaultSelected?: string[]
  onCollapse?: () => void
}

/**
 * Cost vs risk panel — quadrant bubble chart, legend chips that toggle the
 * compared designs, and a bar-list breakdown of cost and risk categories.
 */
function CostVsRiskPanel({
  className,
  designs = allDesigns,
  defaultSelected = ["initial", "liner"],
  onCollapse,
  ...props
}: CostVsRiskPanelProps) {
  const [selected, setSelected] = React.useState<string[]>(defaultSelected)
  const [xAxis, setXAxis] = React.useState("cost")
  const [yAxis, setYAxis] = React.useState("risk")

  const toggle = (id: string) =>
    setSelected((current) =>
      current.includes(id)
        ? current.length > 1
          ? current.filter((item) => item !== id)
          : current
        : [...current, id]
    )

  const xLabel = axisOptions.find((option) => option.id === xAxis)?.label ?? "Cost"
  const yLabel = axisOptions.find((option) => option.id === yAxis)?.label ?? "Risk"

  return (
    <Panel
      data-slot="cost-vs-risk-panel"
      className={cn("h-full", className)}
      {...props}
    >
      <PanelHeader>
        <PanelTitle className="text-base">
          {selected.length} Selected
        </PanelTitle>
        <PanelActions>
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label="Collapse panel"
            onPress={onCollapse}
          >
            <PanelRightIcon />
          </Button>
        </PanelActions>
      </PanelHeader>
      <PanelContent className="flex flex-col gap-4">
        <div className="flex flex-wrap items-center justify-end gap-2 text-xs text-muted-foreground">
          <span>Compare</span>
          <SelectField
            aria-label="X axis"
            variant="filled"
            size="sm"
            className="w-28"
            selectedKey={xAxis}
            onSelectionChange={(key) => setXAxis(String(key))}
          >
            {axisOptions.map((option) => (
              <SelectFieldItem key={option.id} id={option.id} textValue={option.label}>
                {option.label}
              </SelectFieldItem>
            ))}
          </SelectField>
          <span>and</span>
          <SelectField
            aria-label="Y axis"
            variant="filled"
            size="sm"
            className="w-28"
            selectedKey={yAxis}
            onSelectionChange={(key) => setYAxis(String(key))}
          >
            {axisOptions.map((option) => (
              <SelectFieldItem key={option.id} id={option.id} textValue={option.label}>
                {option.label}
              </SelectFieldItem>
            ))}
          </SelectField>
        </div>

        <QuadrantChart
          designs={designs}
          selected={selected}
          xLabel={xLabel}
          yLabel={yLabel}
        />

        <div
          data-slot="cost-vs-risk-legend"
          className="flex flex-wrap gap-1.5"
          role="group"
          aria-label="Designs"
        >
          {designs.map((design) => {
            const active = selected.includes(design.id)
            return (
              <Chip
                key={design.id}
                size="sm"
                variant={active ? "filled" : "outlined"}
                aria-pressed={active}
                onPress={() => toggle(design.id)}
              >
                <span
                  aria-hidden
                  className="size-2 rounded-[2px]"
                  style={{ background: design.color, opacity: active ? 1 : 0.6 }}
                />
                {design.name}
                {design.isRecommended && <CrownIcon className="size-3" />}
              </Chip>
            )
          })}
        </div>

        <ComparisonList metrics={metrics} designs={designs} selected={selected} />
      </PanelContent>
    </Panel>
  )
}

/** Route-ready page: the panel docked on the right of an empty canvas. */
export default function CostVsRiskPanelPage() {
  return (
    <div
      data-slot="cost-vs-risk-panel-page"
      className="flex h-svh w-full bg-background text-foreground"
    >
      <div className="hidden min-w-0 flex-1 items-center justify-center p-6 text-sm text-muted-foreground md:flex">
        Well design comparison
      </div>
      <div className="flex h-full w-full max-w-md shrink-0 flex-col border-l border-border-subtle">
        <CostVsRiskPanel variant="flat" className="rounded-none border-0" />
      </div>
    </div>
  )
}

export { CostVsRiskPanel, QuadrantChart, ComparisonList }
export { designs, metrics, axisOptions, riskLabel } from "./data"
export type { CostVsRiskPanelProps }
export type { DesignPoint, Metric, MetricCategory, MetricValue } from "./data"

export type DesignPoint = {
  id: string
  name: string
  /** Chart series colour token, e.g. `var(--chart-1)`. */
  color: string
  /** Total cost in $M (mid estimate). */
  cost: number
  costRange: [number, number]
  /** Aggregate risk score 0–100. */
  risk: number
  riskRange: [number, number]
  /** Bubble size — plan days. */
  planDays: number
  isRecommended?: boolean
}

export type MetricValue = {
  value: number
  range?: [number, number]
}

export type MetricCategory = {
  id: string
  label: string
  values: Record<string, MetricValue>
}

export type Metric = {
  id: "cost" | "risk"
  label: string
  /** Formats a value for display. */
  format: (value: number) => string
  /** Upper bound used to scale the bars. */
  max: number
  total: MetricCategory
  categories: MetricCategory[]
}

