    name: "Initial Design",
    color: "var(--chart-1)",
    cost: 105,
    costRange: [98, 112],
    risk: 78,
    riskRange: [72, 83],
    planDays: 38,
    isRecommended: true,
  },
  {
    id: "dls",
    name: "Reduced DLS",
    color: "var(--chart-3)",
    cost: 121,
    costRange: [113, 129],
    risk: 61,
    riskRange: [55, 66],
    planDays: 34,
  },
  {
    id: "htdp",
    name: "HTDP",
    color: "var(--chart-5)",
    cost: 142,
    costRange: [131, 152],
    risk: 46,
    riskRange: [40, 52],
    planDays: 31,
  },
  {
    id: "liner",
