          initial: { value: 46 },
          dls: { value: 38 },
          htdp: { value: 29 },
          liner: { value: 6 },
        },
      },
    ],
  },
]

export const axisOptions = [
  { id: "cost", label: "Cost" },
  { id: "risk", label: "Risk" },
  { id: "days", label: "Plan days" },
]

export function riskLabel(value: number): string {
  if (value >= 67) return "High"
  if (value >= 34) return "Medium"
  return "Low"
}
